import { Controller } from "@hotwired/stimulus"
import { formatLocalTime, parseLocalTime } from "helpers/local_time_helpers"

// Renders the raw timestamp carried in a <time datetime="..."> element as
// words, in the viewer's own timezone. Re-renders whenever the timestamp or
// contents change (e.g. after a Turbo morph refresh).
export default class extends Controller {
  static values = { style: { type: String, default: "datetime" } }

  connect() {
    this.render()
    this.observer = new MutationObserver(() => this.render())
    this.observer.observe(this.element, { childList: true, characterData: true, subtree: true, attributeFilter: [ "datetime" ] })
  }

  disconnect() {
    this.observer.disconnect()
  }

  render() {
    const text = formatLocalTime(parseLocalTime(this.element.getAttribute("datetime")), this.styleValue)

    if (this.element.textContent !== text) {
      this.element.textContent = text
    }
  }
}
